import java.util.*;

public class Solution {

    /* ----------  Estrutura da árvore  ---------- */
    private static class Node {
        int value;
        Node left, right;

        Node(int v) { this.value = v; }
    }

    /* ----------  Inserção na BST  ---------- */
    private static Node insert(Node root, int v) {
        if (root == null) return new Node(v);
        if (v < root.value) root.left  = insert(root.left,  v);
        else                root.right = insert(root.right, v);
        return root;
    }

    /* ----------  Pre‑ordem (para impressão)  ---------- */
    private static void preOrder(Node root, List<Integer> out) {
        if (root == null) return;
        out.add(root.value);
        preOrder(root.left,  out);
        preOrder(root.right, out);
    }

    /* ----------  Contar elementos menores que N  ---------- */
    private static int countLess(Node root, int n) {
        if (root == null) return 0;
        if (root.value < n) {
            // todos os nós da sub‑esquerda são menores que n
            return 1 + countNodes(root.left) + countLess(root.right, n);
        } else {
            // o nó atual e a sub‑direita não podem conter valores < n
            return countLess(root.left, n);
        }
    }

    /* ----------  Auxiliar: contar nós de uma sub‑árvore  ---------- */
    private static int countNodes(Node root) {
        if (root == null) return 0;
        return 1 + countNodes(root.left) + countNodes(root.right);
    }

    /* ----------  Programa principal  ---------- */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        /* 1ª linha – elementos a inserir */
        String line = sc.nextLine().trim();
        if (line.isEmpty()) return;          // caso de entrada vazia
        String[] parts = line.split("\\s+");
        Node root = null;
        for (String p : parts) root = insert(root, Integer.parseInt(p));

        /* 2ª linha – N */
        int N = Integer.parseInt(sc.nextLine().trim());

        /* Imprimir a árvore em pré‑ordem */
        List<Integer> pre = new ArrayList<>();
        preOrder(root, pre);
        System.out.println(Arrays.toString(pre.toArray()));

        /* Imprimir a quantidade de elementos menores que N */
        System.out.println(countLess(root, N));
    }
}
```

