import java.util.Scanner;

public class Solution {

    /* ---------- Estrutura da fila ---------- */
    private final int[] data;   // array que armazena os elementos
    private final int capacity; // tamanho máximo da fila
    private int head = -1;      // índice do primeiro elemento
    private int tail = -1;      // índice do último elemento

    public Solution(int capacity) {
        this.capacity = capacity;
        this.data = new int[capacity];
    }

    /* ---------- Operações auxiliares ---------- */
    private boolean isEmpty() {
        return head == -1;
    }

    private boolean isFull() {
        return ((tail + 1) % capacity) == head;
    }

    /* ---------- Operações da fila ---------- */
    public boolean add(int value) {
        if (isFull()) return false;          // não há espaço
        if (isEmpty()) {                     // primeira inserção
            head = tail = 0;
        } else {
            tail = (tail + 1) % capacity;    // avança o tail circularmente
        }
        data[tail] = value;
        return true;
    }

    public boolean remove() {
        if (isEmpty()) return false;         // nada a remover
        if (head == tail) {                  // último elemento
            head = tail = -1;
        } else {
            head = (head + 1) % capacity;    // avança o head circularmente
        }
        return true;
    }

    public int element() {
        if (isEmpty()) throw new IllegalStateException("Queue is empty");
        return data[head];
    }

    public void print() {
        if (isEmpty()) {
            System.out.println("empty");
            return;
        }

        StringBuilder sb = new StringBuilder();
        int i = head;
        while (true) {
            sb.append(data[i]);
            if (i == tail) break;
            sb.append(' ');
            i = (i + 1) % capacity;
        }
        System.out.println(sb);
    }

    /* ---------- Programa principal ---------- */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int cap = Integer.parseInt(sc.nextLine().trim());
        Solution queue = new Solution(cap);

        while (true) {
            String line = sc.nextLine().trim();
            if ("end".equals(line)) break;

            if (line.startsWith("add")) {
                int value = Integer.parseInt(line.split("\\s+")[1]);
                if (!queue.add(value)) System.out.println("full");
            } else if ("remove".equals(line)) {
                if (!queue.remove()) System.out.println("empty");
            } else if ("element".equals(line)) {
                if (queue.isEmpty()) System.out.println("empty");
                else System.out.println(queue.element());
            } else if ("print".equals(line)) {
                queue.print();
            }
        }
    }
}
```

**Por que essa solução funciona**

1. **Fila circular** – `head` e `tail` são atualizados usando módulo (`% capacity`), permitindo reutilizar posições já vazias.
2. **Sem coleções** – Apenas um array de `int` é usado; nenhuma classe de `java.util` além de `Scanner` (para entrada) aparece.
3. **Comportamento correto** – Cada operação devolve `true`/`false` indicando sucesso; o `main` interpreta esses valores e imprime as mensagens exigidas (`full`, `empty`).
