import java.util.Scanner;

public class Solution {

    /* ----------  BST  ---------- */
    private static class Node {
        int value;
        Node left, right;

        Node(int v) { this.value = v; }
    }

    private static class BST {
        private Node root;

        void add(int v) {
            if (root == null) {
                root = new Node(v);
            } else {
                add(root, v);
            }
        }

        private void add(Node n, int v) {
            if (v < n.value) {
                if (n.left == null) n.left = new Node(v);
                else add(n.left, v);
            } else {                     // v > n.value (não há repetidos)
                if (n.right == null) n.right = new Node(v);
                else add(n.right, v);
            }
        }

        int countLeaves() {
            return countLeaves(root);
        }

        private int countLeaves(Node n) {
            if (n == null) return 0;                 // árvore vazia
            if (n.left == null && n.right == null)   // nó folha
                return 1;
            return countLeaves(n.left) + countLeaves(n.right);
        }
    }

    /* ----------  Main  ---------- */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String line = sc.nextLine().trim();
