    /** Radix‑sort estável para um único dígito (0‑9). */
    private static String[] countingSortByDigit(String[] arr, int digitIndex) {
        int[] count = new int[10];          // 0‑9

        // conta ocorrências
        for (String plate : arr) {
            int digit = plate.charAt(digitIndex) - '0';
            count[digit]++;
        }

        // prefix sums – posição final de cada dígito
        for (int i = 1; i < count.length; i++) {
