/*  HashSet baseado em array, endereçamento aberto e probing linear   */
class HashSetOpenAddressing {
    private final Integer[] table;   // armazena os valores
    private final boolean[] deleted; // marcações de “excluído”
    private final int size;

    public HashSetOpenAddressing(int size) {
        this.size = size;
        table   = new Integer[size];
        deleted = new boolean[size];
    }

    /* hash base: key % M */
    private int hash(int key) {
        return key % size;
    }

    /* insere um valor – se já existir não faz nada */
    public void put(int value) {
        int firstDeleted = -1;          // primeiro índice “excluído” encontrado

        for (int i = 0; i < size; i++) {
            int pos = (hash(value) + i) % size;

            if (table[pos] == null) {   // posição vazia
                if (deleted[pos]) {     // “excluído”
                    if (firstDeleted == -1) firstDeleted = pos;
                } else {                // nunca usada
                    table[pos] = value;
                    deleted[pos] = false;
                    return;
                }
            } else if (table[pos].equals(value)) { // já existe
                return;
            }
            /* caso contrário, slot ocupado – continua probing */
        }

        /* tabela cheia ou só slots “excluídos” */
        if (firstDeleted != -1) {
            table[firstDeleted] = value;
            deleted[firstDeleted] = false;
        }
        /* se não houver espaço, a operação é ignorada – conforme enunciado */
    }

    /* remove um valor – marca como “excluído” */
    public void remove(int value) {
        for (int i = 0; i < size; i++) {
            int pos = (hash(value) + i) % size;

            if (table[pos] == null) {
                if (!deleted[pos]) return;   // nunca usado – não encontrado
                /* caso “excluído”, continua probing */
            } else if (table[pos].equals(value)) {
                table[pos] = null;
                deleted[pos] = true;
                return;
            }
        }
    }

    /* verifica se o valor está presente */
    public boolean contains(int value) {
        for (int i = 0; i < size; i++) {
            int pos = (hash(value) + i) % size;

            if (table[pos] == null) {
                if (!deleted[pos]) return false;   // nunca usado – não encontrado
                /* caso “excluído”, continua probing */
            } else if (table[pos].equals(value)) {
                return true;
            }
        }
        return false;
    }

    /* imprime o estado da tabela (Array.toString) */
    public void print() {
        System.out.println(Arrays.toString(table));
    }
}
```

**Principais pontos da solução**

