```java
import java.util.Scanner;

public class Solution {

    /* ----------  Node of a BST  ---------- */
    private static class Node {
        int value;
        Node left, right;

        Node(int v) { this.value = v; }

        /* insert a new value into the subtree rooted at this node */
        void add(int v) {
            if (v < value) {
                if (left == null) left = new Node(v);
                else left.add(v);
            } else {                     // v > value (duplicates are not allowed)
                if (right == null) right = new Node(v);
                else right.add(v);
            }
        }

        /* count internal nodes in the subtree rooted at this node */
        int countInternal() {
            if (left == null && right == null) return 0;   // leaf
            int leftCnt  = (left  == null) ? 0 : left.countInternal();
            int rightCnt = (right == null) ? 0 : right.countInternal();
            return 1 + leftCnt + rightCnt;                 // this node is internal
        }
    }

    /* ----------  Main program  ---------- */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLine()) {          // no input – nothing to count
            System.out.println(0);
            return;
        }

        String line = sc.nextLine().trim();
        if (line.isEmpty()) {             // empty line – no nodes
            System.out.println(0);
            return;
        }

        String[] parts = line.split("\\s+");
        Node root = null;
        for (String p : parts) {
            int v = Integer.parseInt(p);
            if (root == null) root = new Node(v);
            else root.add(v);
        }

        int internal = (root == null) ? 0 : root.countInternal();
        System.out.println(internal);
    }
}
