        void add(int v) {
            if (v < value) {
                if (left == null) left = new Node(v);
                else left.add(v);
            } else if (v > value) {          // não há repetidos
                if (right == null) right = new Node(v);
                else right.add(v);
            }
        }

        /* Percurso pré‑ordem que grava os valores em uma lista */
        void preOrder(List<Integer> out) {
            out.add(value);
            if (left != null)  left.preOrder(out);
            if (right != null) right.preOrder(out);
        }
    }

    /* ----------  Contagem de elementos maiores que N  ---------- */
    private static int countGreater(Node node, int n) {
        if (node == null) return 0;

        if (node.value > n) {
            /* O próprio nó + todos os nós da sub‑árvore direita
               (todos > node.value > n) + nós da sub‑árvore esquerda
               que ainda podem ser > n */
            return 1 + countGreater(node.left, n) + countGreater(node.right, n);
        } else {
            /* Se o nó atual não é > n, então apenas a sub‑árvore direita
               pode conter valores > n */
            return countGreater(node.right, n);
        }
    }

