import java.util.Scanner;

/*  Node – nó da lista duplamente encadeada  */
class Node {
    int value;
    Node next;
    Node prev;

    Node(int v) {
        value = v;
        next  = null;
        prev  = null;
    }
}

/*  Fila – implementação baseada em lista duplamente encadeada  */
class Fila {
    private Node head;   // primeiro elemento
    private Node tail;   // último elemento
    private int  size;   // tamanho da fila

    /* construtor */
    Fila() {
        head = null;
        tail = null;
        size = 0;
    }

    /* ----------  Operações básicas  ---------- */

    /*  Enfileira um elemento (add)  */
    void add(int v) {
        Node n = new Node(v);
        if (isEmpty()) {                 // fila vazia
            head = tail = n;
        } else {                         // fila não vazia
            tail.next = n;
            n.prev   = tail;
            tail     = n;
        }
        size++;
    }

    /*  Desenfileira o primeiro elemento (remove)  */
    boolean remove() {
        if (isEmpty()) return false;     // fila vazia
        if (head == tail) {              // apenas um elemento
            head = tail = null;
        } else {
            head = head.next;
            head.prev = null;
        }
        size--;
        return true;
    }

    /*  Retorna o elemento inicial (element)  */
    int element() {
        return head.value;
    }

    /*  Busca a primeira posição de um valor (search)  */
    int search(int v) {
        return searchRec(head, v, 0);
    }

    /*  Imprime a fila (print)  */
    String toString() {
        if (isEmpty()) return "empty";
        return toStringRec(head);
    }

    /*  Verifica se a fila está vazia  */
    boolean isEmpty() {
        return head == null;
    }

    /* ----------  Métodos recursivos  ---------- */

    /*  Busca recursiva  */
    private int searchRec(Node n, int v, int idx) {
        if (n == null) return -1;          // fim da lista
        if (n.value == v) return idx;      // encontrado
        return searchRec(n.next, v, idx + 1);
    }

    /*  Impressão recursiva  */
    private String toStringRec(Node n) {
        if (n == null) return "";
        String rest = toStringRec(n.next);
        return n.value + (rest.isEmpty() ? "" : " " + rest);
    }
}

/*  Programa principal  */
public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Fila fila = new Fila();

        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.equals("end")) break;

            if (line.startsWith("add")) {
                int v = Integer.parseInt(line.split("\\s+")[1]);
                fila.add(v);

            } else if (line.equals("remove")) {
                if (!fila.remove()) System.out.println("empty");

            } else if (line.equals("element")) {
                if (fila.isEmpty()) System.out.println("empty");
                else System.out.println(fila.element());

            } else if (line.startsWith("search")) {
                int v = Integer.parseInt(line.split("\\s+")[1]);
                System.out.println(fila.search(v));

            } else if (line.equals("print")) {
                System.out.println(fila);
            }
        }
        sc.close();
    }
}
