import java.util.Scanner;

public class Solution {

    /* ----------  BST  ---------- */
    private static class Node {
        int value;
        Node left, right;

        Node(int v) { this.value = v; }
    }

    private static Node root;

    /* insere um valor na BST */
    private static void add(int v) {
        if (root == null) {
            root = new Node(v);
            return;
        }
        Node cur = root;
        while (true) {
            if (v < cur.value) {
                if (cur.left == null) {
                    cur.left = new Node(v);
                    break;
                }
                cur = cur.left;
            } else {                     // v > cur.value (não há repetidos)
                if (cur.right == null) {
                    cur.right = new Node(v);
                    break;
                }
                cur = cur.right;
            }
        }
    }

    /* devolve o caminho até o mínimo (lista de valores) */
    private static String minPath() {
        StringBuilder sb = new StringBuilder();
        Node cur = root;
        while (cur != null) {
            sb.append(cur.value);
            if (cur.left != null) sb.append(' ');
            cur = cur.left;
        }
        return sb.toString();
    }

    /* ----------  main  ---------- */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLine()) return;          // caso de entrada vazia
