```java
import java.util.*;

public class Solucao {

    private int[] arr;          // array original
    private int[] helper;       // auxiliar para o merge

    public Solucao(int[] arr) {
        this.arr = arr;
        this.helper = new int[arr.length];
    }

    /* ----------  Merge‑Sort  ---------- */
    public void mergeSort(int low, int high) {
        if (low < high) {
            int mid = low + (high - low) / 2;

            // 1. Imprime o sub‑array que será dividido
            imprimir(low, mid);
            mergeSort(low, mid);

            imprimir(mid + 1, high);
            mergeSort(mid + 1, high);

            // 2. Faz o merge e imprime o resultado
            merge(low, mid, high);
        }
    }

    /* ----------  Merge  ---------- */
    private void merge(int low, int mid, int high) {
        // Copia para o auxiliar
        for (int i = low; i <= high; i++) {
            helper[i] = arr[i];
        }

        int i = low;        // ponteiro no primeiro sub‑array
        int j = mid + 1;    // ponteiro no segundo sub‑array
        int k = low;        // posição de escrita no array original

        while (i <= mid && j <= high) {
            if (helper[i] <= helper[j]) {
                arr[k++] = helper[i++];
            } else {
                arr[k++] = helper[j++];
            }
        }

        // Copia o restante do primeiro sub‑array (se houver)
        while (i <= mid) {
            arr[k++] = helper[i++];
        }

        // Copia o restante do segundo sub‑array (se houver)
        while (j <= high) {
            arr[k++] = helper[j++];
        }

        // 3. Imprime o sub‑array já ordenado
        imprimir(low, high);
    }

    /* ----------  Impressão  ---------- */
    private void imprimir(int low, int high) {
        System.out.println(Arrays.toString(Arrays.copyOfRange(arr, low, high + 1)));
