```java
import java.util.Arrays;
import java.util.Scanner;

public class Solution {

    /** Counting sort estável que ordena o vetor a[] de acordo com o dígito nthDig
     *  (1 = menor, d = maior). Os dígitos são 0‑9. */
    private static int[] countingSortByDigit(int[] a, int nthDig) {
        final int RADIX = 10;                 // dígitos 0‑9
        int[] count = new int[RADIX];         // frequência de cada dígito

        // 1. Frequência
        int pow10 = (int) Math.pow(10, nthDig - 1);
        for (int value : a) {
            int digit = (value / pow10) % 10;
            count[digit]++;
        }

        // 2. Cumulativa (para posição final de cada dígito)
        for (int i = 1; i < RADIX; i++) {
            count[i] += count[i - 1];
        }

        // 3. Construção do vetor ordenado (estável)
        int[] sorted = new int[a.length];
        for (int i = a.length - 1; i >= 0; i--) {
            int digit = (a[i] / pow10) % 10;
            sorted[--count[digit]] = a[i];
        }

        return sorted;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // 1ª linha: sequência de inteiros
        String[] tokens = sc.nextLine().trim().split("\\s+");
