    public static void quickSort(int[] v, int ini, int fim) {

        if (ini < fim) {
            int pos_pivot = hoare(v, ini, fim);
            quickSort(v, ini, pos_pivot);
            quickSort(v, pos_pivot + 1, fim);
        }

