        }

        StringTokenizer st = new StringTokenizer(line);
        int[] nums = new int[st.countTokens()];
        int idx = 0;
        int max = 0;

        while (st.hasMoreTokens()) {
            int v = Integer.parseInt(st.nextToken());
            nums[idx++] = v;
            if (v > max) max = v;
        }

