import java.util.Scanner;

public class Solution {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // 1ª linha: sequência ordenada de inteiros
        String[] tokens = sc.nextLine().trim().split("\\s+");
        int[] arr = new int[tokens.length];
        for (int i = 0; i < tokens.length; i++) {
            arr[i] = Integer.parseInt(tokens[i]);
        }

        // 2ª linha: número a ser pesquisado
        int target = Integer.parseInt(sc.nextLine().trim());

        binarySearch(arr, 0, arr.length - 1, target);
    }

    /**
     * Busca binária recursiva que imprime os índices visitados.
     *
     * @param arr   array ordenado
     * @param left  índice esquerdo do intervalo atual
     * @param right índice direito do intervalo atual
     * @param target valor a ser encontrado
     * @return índice do target ou -1 se não encontrado
     */
    private static int binarySearch(int[] arr, int left, int right, int target) {
        if (left > right) {          // intervalo vazio → não encontrado
            System.out.println("-1");
            return -1;
        }

        int mid = (left + right) / 2;
        System.out.println(mid);     // índice visitado

        if (arr[mid] == target) {
            return mid;
        } else if (target < arr[mid]) {
            return binarySearch(arr, left, mid - 1, target);
        } else {
            return binarySearch(arr, mid + 1, right, target);
        }
    }
}
