        /* Insere um valor na sub‑árvore */
        void add(int v) {
            if (v < value) {
                if (left == null) left = new Node(v);
                else left.add(v);
            } else {                     // v > value (não há repetidos)
                if (right == null) right = new Node(v);
                else right.add(v);
            }
        }
    }

    /* ----------  Construção da BST  ---------- */
    private static Node root = null;

    private static void add(int v) {
        if (root == null) root = new Node(v);
        else root.add(v);
    }

    /* ----------  Caminho até o máximo  ---------- */
    private static void printMaxPath() {
        Node cur = root;
        StringBuilder sb = new StringBuilder();
        while (cur != null) {
            sb.append(cur.value);
            if (cur.right != null) sb.append(' ');
            cur = cur.right;          // sempre seguimos para a direita
        }
        System.out.println(sb);
    }

